inline constexpr const char* xck_gga_ua_o2_batch_field_names[] = {"w", "rho_a_x", "rho_a_y", "rho_a_z", "rho_b_x", "rho_b_y", "rho_b_z", "rho_a_p1_x", "rho_a_p1_y", "rho_a_p1_z", "rho_b_p1_x", "rho_b_p1_y", "rho_b_p1_z", "rho_a_p1", "rho_b_p1"};
